with department_summary as (select dept_id, sum(case when job_title = 'Engineer' then salary else 0 end) as engineer_salary, concat_ws(', ', sort_array(collect_set(level))) as level_values from employees group by dept_id) select d.location, d.budget, ds.engineer_salary, ds.level_values from departments d left join department_summary ds on d.id = ds.dept_id where ds.engineer_salary > 63 order by d.budget
